// t02: the simple (single column) cash book: format, recording, balancing and posting to the ledger. Cash books and
// ledger accounts are generated by cb.mjs and acc.mjs; every closing balance is asserted.
import { mcq, ar, tf, fb, short, long } from './lib.mjs';
import { same, check, inr, rs, mdTable, cashBook, R, P, ledgerFromBook } from './fig.mjs';
import { QQ, numQ } from './qq.mjs';

// ================================================================ multiple choice
QQ('m_cb_roles', mcq({
  t: 2, d: 1, c: 'understanding',
  stem: 'A trader who keeps a cash book writes cash receipts and payments in it directly, and does not open a separate Cash A/c in the ledger. This is possible because the cash book',
  opts: ['is a book of first entry and is also balanced like the Cash A/c', 'records only those cash items that are not entered anywhere else', 'is written up from the journal at the end of every month', 'is kept for statistical purposes and has no accounting value'],
  sol: 'Transactions are entered in it first, and its two sides, receipts and payments, make it the cash account itself. It is not written up from the journal, it does not leave out items, and it is part of the formal books.',
}));
{
  const open = 39800;
  QQ('m_cash_nocredit', mcq({
    t: 2, d: 3, c: 'analysis',
    stem: `The clerk of Harsh Optics, an imagined shop, totals the debit side of the simple cash book, opening cash included, as ${rs(open)} and the credit side, before balancing, as ${rs(41300)}. The right conclusion is that`,
    opts: ['there is an error, because cash paid out cannot exceed cash held, so the entries must be rechecked', `a credit balance of ${rs(41300 - open)} is carried down on the debit side`, `the firm has earned a profit of ${rs(41300 - open)}`, `the firm has taken an overdraft of ${rs(41300 - open)} from its bank`],
    sol: `A shop can pay out only the cash it has, so payments of ${inr(41300)} against ${inr(open)} cannot both be right. A receipt was left out or a payment was entered wrongly. A credit balance in cash is not carried down, the excess of payments is not a profit, and a simple cash book has no bank column in which an overdraft could appear.`,
  }));
}
{
  const o = 12000, rec = [8500, 3300], pay = [6200, 9100];
  const cb = cashBook({ kind: 'simple', open: { cash: o, bank: 0 }, items: [R('2', 'Sales A/c', { cash: rec[0] }), P('5', 'Purchases A/c', { cash: pay[0] }), R('9', 'Sales A/c', { cash: rec[1] }), P('13', 'Wages A/c', { cash: pay[1] })] });
  const key = o + rec[0] + rec[1] - pay[0] - pay[1];
  same(cb.cash, key, 'm_balance_simple');
  const wrong = [rec[0] + rec[1] - pay[0] - pay[1], o + rec[0] + rec[1] + pay[0] + pay[1], rec[0] + rec[1] + pay[0] + pay[1]];
  check(!wrong.includes(key), 'distractors differ from the key');
  QQ('m_balance_simple', mcq({
    t: 2, d: 2, c: 'application',
    stem: `Fatima Garments, an imagined shop, began a month with ${rs(o)} in hand. Its cash receipts were ${rs(rec[0])} and ${rs(rec[1])} and its cash payments were ${rs(pay[0])} and ${rs(pay[1])}. The balance carried down in the cash book is`,
    opts: [rs(key), rs(wrong[0]), rs(wrong[1]), rs(wrong[2])],
    sol: `Closing cash = ${inr(o)} + ${inr(rec[0])} + ${inr(rec[1])} − ${inr(pay[0])} − ${inr(pay[1])} = ${rs(key)}. ${rs(wrong[0])} leaves out the opening cash, ${rs(wrong[1])} adds the payments instead of deducting them, and ${rs(wrong[2])} adds the receipts and payments together without the opening cash.`,
  }));
}
QQ('m_chk_posting', mcq({
  t: 2, d: 2, c: 'application',
  stem: 'Ishwar Dairy, an imagined business, pays rent of ₹6,000 in cash. When this line of its cash book is posted to the Rent A/c in the ledger, it appears',
  opts: ['on the debit side as To Cash A/c', 'on the credit side as By Cash A/c', 'on the debit side as To Rent A/c', 'on the credit side as By Rent A/c'],
  sol: 'The payment is on the credit side of the cash book, so the other account, Rent, is debited and the particulars name the cash book account. An account never names itself, and a credit entry in Rent would be a receipt.',
}));
QQ('m_post_debtor', mcq({
  t: 2, d: 2, c: 'application',
  stem: 'Charu Handlooms, an imagined firm, receives ₹4,500 in cash from a debtor, Rekha Nair, and enters it in its cash book. In the ledger the entry is posted to Rekha Nair\'s account',
  opts: ['on the credit side as By Cash A/c', 'on the debit side as To Cash A/c', 'on the credit side as By Rekha Nair', 'on the debit side as To Sales A/c'],
  sol: 'The receipt is a debit in the cash book, so the debtor is credited, because she owes less. The particulars name Cash, not the debtor herself, and Sales is not touched by a settlement of an earlier sale.',
}));

// ================================================================ assertion-reason, true-false, fill-blank
QQ('ar_cash_nocredit', ar({
  t: 2, d: 2, c: 'understanding', verdict: 'both-true-explains',
  a: 'The cash balance brought down in the cash book of a trading firm is always on the debit side.',
  r: 'Cash payments are made out of the cash held, so they cannot exceed the opening cash plus the receipts.',
  sol: 'Both are true, and R gives the reason: with payments never above opening cash plus receipts, the debit side is at least as large as the credit side, so the balance is a debit or nil.',
}));
QQ('tf_cb_sep', tf({
  t: 2, d: 2, c: 'understanding', ans: false,
  stem: 'A firm that keeps a simple cash book must also open a Cash A/c in its ledger and post every cash book total to it.',
  sol: 'The cash book is itself the cash account, balanced in the same way, so a second Cash A/c would record every cash item twice. Only the other accounts of each line are posted.',
}));
QQ('fb_chk_cashbal', fb({
  t: 2, d: 1, c: 'recall',
  stem: 'When the cash book is balanced, the cash in hand is written as ___ on the credit side and brought down on the ___ side below the totals.',
  acc: [['balance c/d', 'c/d', 'carried down'], ['debit']],
  sol: 'The balance is carried down on the credit side as balance c/d and brought down on the debit side, since cash in hand is a debit balance.',
}));
QQ('fb_simple', fb({
  t: 2, d: 1, c: 'recall',
  stem: 'In a simple cash book every receipt is written on the ___ side and every payment on the ___ side.',
  acc: [['debit'], ['credit']],
  sol: 'Receipts debit the cash account, so they stand on the debit side, and payments are on the credit side.',
}));

// ================================================================ numerical
{
  const cb = cashBook({
    kind: 'simple', open: { cash: 9400, bank: 0 },
    items: [R('2', 'Sales A/c', { cash: 22600 }), P('5', 'Purchases A/c', { cash: 14750 }), R('9', 'Meera Pillai', { cash: 5300 }), P('12', 'Wages A/c', { cash: 4600 }), R('17', 'Commission Received A/c', { cash: 1200 }), P('21', 'Drawings A/c', { cash: 3000 }), P('27', 'Stationery A/c', { cash: 380 })],
  });
  const rcpt = 9400 + 22600 + 5300 + 1200;
  const paid = 14750 + 4600 + 3000 + 380;
  same(rcpt, 38500, 'n_simple_close receipts');
  same(paid, 22730, 'n_simple_close payments');
  same(cb.cash, rcpt - paid, 'n_simple_close');
  QQ('n_simple_close', numQ({
    t: 2, d: 2, c: 'application', value: cb.cash,
    stem: `Sanvi Bakery, an imagined shop, had ${rs(9400)} in hand on 1 September. In the month it made cash sales of ${rs(22600)}, bought goods for cash for ${rs(14750)}, received ${rs(5300)} from Meera Pillai, paid wages of ${rs(4600)}, received commission of ${rs(1200)}, took ${rs(3000)} for personal use and paid ${rs(380)} for stationery. Find the balance carried down in the cash book (in ₹).`,
    sol: `Receipts with the opening cash = ${inr(9400)} + ${inr(22600)} + ${inr(5300)} + ${inr(1200)} = ${inr(rcpt)}; payments = ${inr(14750)} + ${inr(4600)} + ${inr(3000)} + ${inr(380)} = ${inr(paid)}; balance = ${inr(rcpt)} − ${inr(paid)} = ${rs(cb.cash)}.`,
  }));
}
{
  const rec = 61400, pay = 52750, close = 14150;
  const open = close + pay - rec;
  same(open, 5500, 'n_missing_open');
  cashBook({ kind: 'simple', open: { cash: open, bank: 0 }, items: [R('1', 'Sales A/c', { cash: rec }), P('2', 'Purchases A/c', { cash: pay })] });
  QQ('n_missing_open', numQ({
    t: 2, d: 3, c: 'application', value: open,
    stem: `The cash book of Leela Textiles, an imagined firm, shows receipts of ${rs(rec)} and payments of ${rs(pay)} during a quarter, apart from the opening balance, and a balance carried down of ${rs(close)}. Find the cash in hand at the beginning of the quarter (in ₹).`,
    sol: `Both sides total the same, so opening cash + ${inr(rec)} = ${inr(pay)} + ${inr(close)}. Opening cash = ${inr(pay)} + ${inr(close)} − ${inr(rec)} = ${rs(open)}.`,
  }));
}

// ================================================================ short answer, 2 marks
QQ('s2_cb_roles', short({
  t: 2, d: 2, c: 'understanding', marks: 2,
  stem: 'Cash transactions are entered in the cash book, and no Cash A/c is opened in the ledger. Give two reasons.',
  model: '1. The cash book is a **book of original entry**: each cash receipt and payment is first recorded in it, in date order.\n2. It is **balanced like a ledger account**, with receipts on the debit side and payments on the credit side, so it already serves as the Cash A/c and a second account would only repeat it.',
  sol: 'The cash book is both a journal for cash and the cash account.',
  scheme: [['Reason 1: first entry of cash transactions', 1], ['Reason 2: balanced like the cash account, so no separate account', 1]],
}));
QQ('s2_cash_credit', short({
  t: 2, d: 3, c: 'analysis', marks: 2,
  stem: 'After balancing, the cashier of Rohini Crafts, an imagined firm, finds that the credit side of the cash book exceeds the debit side by ₹1,200. Explain why this cannot be correct and name two likely causes.',
  model: 'Cash in hand can never be a credit balance: the firm cannot pay out more cash than it held plus what it received. The difference shows a mistake.\n\nLikely causes: (i) a **receipt was omitted** or posted to the wrong side; (ii) a **payment was entered twice** or with a larger amount than was paid.',
  sol: 'Impossibility of a negative cash balance, then two causes.',
  scheme: [['Reason: cash paid cannot exceed cash held', 1], ['Two likely causes: omitted receipt, payment overstated or entered twice', 1]],
}));

// ================================================================ short answer, 3 marks
{
  const cb = cashBook({
    kind: 'simple', open: { cash: 7200, bank: 0 }, openDate: '1 Aug', closeDate: '31 Aug', next: '1 Sep',
    items: [R('4 Aug', 'Sales A/c', { cash: 15600 }), P('7 Aug', 'Purchases A/c', { cash: 8900 }), R('13 Aug', 'Commission Received A/c', { cash: 950 }), P('18 Aug', 'Wages A/c', { cash: 3400 }), P('24 Aug', 'Carriage A/c', { cash: 480 })],
  });
  same(cb.cash, 7200 + 15600 + 950 - 8900 - 3400 - 480, 's3_simple_cb');
  QQ('s3_simple_cb', short({
    t: 2, d: 3, c: 'application', marks: 3,
    stem: `Prepare the simple cash book of Nitin Hardware, an imagined shop, for August 2027 and balance it. Cash in hand on 1 August: ${rs(7200)}. 4 Aug: cash sales ${rs(15600)}. 7 Aug: goods bought for cash ${rs(8900)}. 13 Aug: commission received ${rs(950)}. 18 Aug: wages paid ${rs(3400)}. 24 Aug: carriage paid ${rs(480)}.`,
    model: `${cb.md}\n\nThe balance of ${rs(cb.cash)} is carried down on the credit side and brought down on 1 September as a debit balance.`,
    sol: 'Receipts and opening cash on the debit side, payments on the credit side, then the balance and the equal totals.',
    scheme: [['Debit side: opening cash and both receipts, each with its other account', 1], ['Credit side: the three payments with their other accounts', 1], [`Balance c/d ${rs(cb.cash)} on the credit side, equal totals ${rs(cb.dr.cash)} and b/d on the debit side`, 1]],
  }));
}
{
  const cb = cashBook({
    kind: 'simple', open: { cash: 20000, bank: 0 },
    items: [R('12 Jun', 'Kiran Saha', { cash: 5000 }), P('15 Jun', 'Prem Dyers', { cash: 6000 }), R('26 Jun', 'Kiran Saha', { cash: 2000 }), R('28 Jun', 'Sales A/c', { cash: 9100 })],
  });
  const kiran = ledgerFromBook(cb, 'Kiran Saha', { opening: { side: 'dr', amount: 7500 } });
  const prem = ledgerFromBook(cb, 'Prem Dyers', { opening: { side: 'cr', amount: 11000 } });
  same(kiran.balance, 500, 's3_post_two Kiran');
  same(prem.balance, -5000, 's3_post_two Prem');
  QQ('s3_post_two', short({
    t: 2, d: 3, c: 'application', marks: 3,
    stem: `In the books of Charu Handlooms, an imagined firm, Kiran Saha owed ${rs(7500)} and the firm owed ${rs(11000)} to Prem Dyers on 1 June 2027. The cash book shows: 12 Jun received ${rs(5000)} from Kiran Saha; 15 Jun paid ${rs(6000)} to Prem Dyers; 26 Jun received ${rs(2000)} from Kiran Saha. Post these items to the two ledger accounts and balance them.`,
    model: `**Kiran Saha A/c**\n\n${kiran.md}\n\n**Prem Dyers A/c**\n\n${prem.md}\n\nKiran Saha still owes ${rs(kiran.balance)} (debit balance); the firm still owes Prem Dyers ${rs(-prem.balance)} (credit balance).`,
    sol: 'Receipts credit the debtor, payments debit the creditor; each account is then balanced.',
    scheme: [['Kiran Saha A/c: opening balance and two receipts on the credit side by Cash A/c', 1], ['Prem Dyers A/c: opening balance and the payment by To Cash A/c', 1], [`Both balanced: ${rs(kiran.balance)} debit and ${rs(-prem.balance)} credit, totals equal`, 1]],
  }));
}

// ================================================================ long answer, 5 marks
{
  const cb = cashBook({
    kind: 'simple', open: { cash: 16500, bank: 0 }, openDate: '1 Oct', closeDate: '31 Oct', next: '1 Nov',
    items: [
      R('3 Oct', 'Sales A/c', { cash: 18400 }), P('5 Oct', 'Purchases A/c', { cash: 11250 }), R('8 Oct', 'Tarun Gupta', { cash: 6000 }),
      P('11 Oct', 'Rent A/c', { cash: 4000 }), P('14 Oct', 'Salaries A/c', { cash: 8500 }), R('18 Oct', 'Interest Received A/c', { cash: 700 }),
      P('21 Oct', 'Bhola Brothers', { cash: 5600 }), P('25 Oct', 'Drawings A/c', { cash: 2500 }), R('29 Oct', 'Sales A/c', { cash: 7300 }),
    ],
  });
  same(cb.cash, 16500 + 18400 + 6000 + 700 + 7300 - 11250 - 4000 - 8500 - 5600 - 2500, 'l5_simple_cb');
  const tarun = ledgerFromBook(cb, 'Tarun Gupta', { opening: { side: 'dr', amount: 9000 } });
  same(tarun.balance, 3000, 'l5_simple_cb Tarun');
  QQ('l5_simple_cb', long({
    t: 2, d: 3, c: 'application', marks: 5,
    stem: `Record the following in the simple cash book of Ishwar Dairy, an imagined business, for October 2027, balance it, and post the receipt from Tarun Gupta to his account, which showed a debit balance of ${rs(9000)} on 1 October. Cash in hand on 1 October ${rs(16500)}. 3 Oct: cash sales ${rs(18400)}. 5 Oct: goods bought for cash ${rs(11250)}. 8 Oct: received ${rs(6000)} from Tarun Gupta. 11 Oct: rent paid ${rs(4000)}. 14 Oct: salaries paid ${rs(8500)}. 18 Oct: interest received ${rs(700)}. 21 Oct: paid ${rs(5600)} to Bhola Brothers. 25 Oct: drawings ${rs(2500)}. 29 Oct: cash sales ${rs(7300)}.`,
    model: `${cb.md}\n\n**Tarun Gupta A/c**\n\n${tarun.md}`,
    sol: 'Enter every item on its own side with the other account named, balance the cash book, then post the one personal account.',
    scheme: [['Debit side: opening cash and all receipts with the other account named', 1], ['Credit side: all five payments with the other account named', 1], [`Balance c/d ${rs(cb.cash)} on the credit side and equal totals ${rs(cb.dr.cash)}`, 1], ['Balance b/d brought down on the debit side', 1], [`Tarun Gupta A/c posted by Cash A/c and balanced at ${rs(tarun.balance)} debit`, 1]],
  }));
}
void mdTable;
